seq = "".join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

def hamming(a,b): return sum(1 for x,y in zip(a,b) if x!=y)

# search inverted repeat pairs: arm length L, mismatch budget
best=[]
for L in range(12,41):
    for i in range(0,n-L+1):
        arm=seq[i:i+L]
        target=rc(arm)
        # search target in seq downstream within some window
        start=i+L+4  # loop >=4
        end=min(n-L+1, i+L+4+2500)
        pos=seq.find(target, start, end)
        while pos!=-1:
            best.append((L,0,i,pos))
            pos=seq.find(target, pos+1, end)
# also allow mismatches via seed
print("perfect IR arms >=12:", len(best))
for b in sorted(best, reverse=True)[:20]:
    print(b, seq[b[2]:b[2]+b[0]], seq[b[3]:b[3]+b[0]], "loop",b[3]-(b[2]+b[0]))
