n=len(seq)
def runs_diag_self(a, mind=1):
    out=[]
    na=len(a)
    for d in range(mind, na):
        p0 = 0
        p1 = na - d
        p = p0
        while p < p1:
            if a[p]==a[p+d]:
                start=p
                while p<p1 and a[p]==a[p+d]:
                    p+=1
                out.append((start,p-start,d))
            else:
                p+=1
    return out

rr = runs_diag_self(seq)
long = [r for r in rr if r[1]>=9]
long.sort(key=lambda x:-x[1])
print("exact direct repeats >=9 bp:", len(long))
for start,L,d in long:
    print(f"seq1={start+1}-{start+L} seq2={start+d+1}-{start+d+L} L={L} gap={d-L}")
